import{_ as a,o as s,c as o,a2 as i}from"./chunks/framework.YT-FC_Xx.js";const k=JSON.parse('{"title":"升级","description":"","frontmatter":{},"headers":[],"relativePath":"guide/upgrade.md","filePath":"guide/upgrade.md","lastUpdated":1794141383000}'),t={name:"guide/upgrade.md"};function d(l,e,c,n,p,r){return s(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="升级" tabindex="-1">升级 <a class="header-anchor" href="#升级" aria-label="Permalink to &quot;升级&quot;">​</a></h1><h2 id="flyx-命名兼容" tabindex="-1">FLYX 命名兼容 <a class="header-anchor" href="#flyx-命名兼容" aria-label="Permalink to &quot;FLYX 命名兼容&quot;">​</a></h2><p>新安装使用 <code>flyx-panel-backend</code>、<code>flyx-panel-frontend</code>、<code>flyx-panel-postgres</code> 容器，以及 <code>flyx-sqlite-data</code>、<code>flyx-postgres-data</code> 数据卷和 <code>flyx-network</code> 网络。安装脚本会把这些名称写入 <code>.env</code>。</p><p>旧部署升级时继续使用原容器、数据卷和数据库账号，不搬动已有数据。Compose 中保留的旧默认值用于兼容旧版面板直接下载新版配置的升级方式。手动部署如需使用新名称，应显式配置 <code>PANEL_BACKEND_CONTAINER</code>、<code>PANEL_FRONTEND_CONTAINER</code>、<code>PANEL_POSTGRES_CONTAINER</code>、<code>FLYX_SQLITE_VOLUME</code>、<code>FLYX_POSTGRES_VOLUME</code> 和 <code>FLYX_NETWORK</code>；已有部署请填写实际使用的名称，不能将数据卷改成一个空的新卷。自定义部署应在升级前核对这些参数。</p><p>版本变量统一为 <code>FLYX_VERSION</code>，升级脚本同时更新旧的 <code>FLUX_VERSION</code>，供旧模板或回退使用。其他配置优先读取 <code>FLYX_*</code>，未设置时兼容对应的 <code>FLUX_*</code> / <code>FLVX_*</code> 旧名称。通行证密钥的公开 origin 保持原值，浏览器的主题和列表偏好自动兼容旧键。</p><p>节点新安装使用 <code>flyx-agent</code> 服务及 <code>/etc/flyx-agent</code>。旧节点继续在 <code>/etc/flux_agent</code> 中运行 <code>flux_agent</code>，保留配置、内核状态、待上报流量及调优备份。新版程序按自身安装位置执行升级和回退。Docker 重装命令会识别已有容器的数据挂载，镜像拉取成功后才替换容器；发现新旧容器同时存在或挂载不明确时停止。</p><p>已有 nftables 表和计数 epoch 继续沿用，新建状态使用 FLYX 名称，避免仅因项目改名重置统计。只有升级前就已配置的 nftables 服务器会沿用旧的 <code>flvx</code> 表，之后新添加的服务器只使用 <code>flyx</code> 表。内部的用户凭据、数字标记及 API 数据字段保持兼容。旧镜像名作为过渡别名继续发布。</p><h2 id="和-flux-panel-flvx-装在同一台服务器" tabindex="-1">和 flux-panel / FLVX 装在同一台服务器 <a class="header-anchor" href="#和-flux-panel-flvx-装在同一台服务器" aria-label="Permalink to &quot;和 flux-panel / FLVX 装在同一台服务器&quot;">​</a></h2><p>FLYX 3.4.0 之前和 flux-panel、FLVX 用的是同一套名字，所以安装脚本只在确认是 FLYX 自己的旧安装时才沿用旧名字，其他面板的安装不会被接管、改写或删除：</p><ul><li><strong>面板</strong>：已有的 <code>flux-panel-backend</code> 容器只有镜像来自 <code>ghcr.io/kure29/</code>（或 3.9.0 发布时短暂使用的 <code>ghcr.io/seren233/</code>）时才当作 FLYX 的旧部署；新安装默认放在 <code>/opt/flyx-panel</code>（可用 <code>PANEL_DEPLOY_DIR</code> 指定），不会覆盖 <code>/root</code> 里其他面板的 <code>.env</code> 和 <code>docker-compose.yml</code>。默认端口 <code>6366</code> / <code>6365</code> 被占用时，脚本会建议下一个空闲端口。更新、卸载、迁移 PostgreSQL 只处理 FLYX 的部署</li><li><strong>节点脚本安装</strong>：<code>/etc/flux_agent</code> 只有 <code>config.json</code> 里的面板地址和本次安装的一致时才当作 FLYX 的旧节点，否则新装到 <code>/etc/flyx-agent</code>，两个 agent 各自运行；交互菜单里没有面板地址，更新或卸载前会先询问。脚本也不再删除 flux-panel 原版的 <code>gost.service</code> 和 <code>/usr/local/bin/gost</code></li><li><strong>节点 Docker 安装</strong>：已有的 <code>flux_agent</code> 容器只有镜像来自 <code>ghcr.io/kure29/</code>（或 3.9.0 发布时短暂使用的 <code>ghcr.io/seren233/</code>）时才会被替换</li><li><strong>nftables 转发</strong>：FLVX 也用 <code>flvx</code> 表，新添加的服务器不会读写它</li></ul><p>两个面板的 agent 共用宿主机网络，同一个端口只能给其中一个面板的转发使用。</p><p>回退前保留部署目录中的 <code>.env</code>、<code>docker-compose.yml</code> 及备份，使用该安装对应的原配置恢复；新安装回到不识别新资源参数的历史版本时，需要显式保留原数据卷挂载。API Skill 的迁移见 <a href="./../ai-skill">AI Skill</a>。</p><h2 id="面板内升级" tabindex="-1">面板内升级 <a class="header-anchor" href="#面板内升级" aria-label="Permalink to &quot;面板内升级&quot;">​</a></h2><p><strong>设置</strong> → <strong>系统与升级</strong> → <strong>面板自升级</strong> → <strong>检查更新</strong> → <strong>立即升级</strong>。</p><p>升级会拉取新镜像并重建前后端容器，约 1 分钟后刷新页面即可。页面没有变化时，通常是浏览器或 CDN 缓存，刷新或清理缓存即可。</p><h2 id="脚本升级" tabindex="-1">脚本升级 <a class="header-anchor" href="#脚本升级" aria-label="Permalink to &quot;脚本升级&quot;">​</a></h2><p>重新运行安装脚本，选 <code>2. 更新面板</code>。脚本会按运行中容器的标签找到部署目录（新安装默认为 <code>/opt/flyx-panel</code>）；找不到时，在部署目录（存放 <code>docker-compose.yml</code> 和 <code>.env</code> 的目录）里运行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/kure29/flyx/releases/latest/download/panel_install.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> panel_install.sh</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> panel_install.sh</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./panel_install.sh</span></span></code></pre></div><p>数据会保留，更新前会自动备份到部署目录的 <code>backups/</code>。</p><h2 id="指定版本" tabindex="-1">指定版本 <a class="header-anchor" href="#指定版本" aria-label="Permalink to &quot;指定版本&quot;">​</a></h2><p>到 <a href="https://github.com/kure29/flyx/releases" target="_blank" rel="noreferrer">Releases</a> 复制对应版本的命令，例如：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/kure29/flyx/releases/download/3.0.7/panel_install.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> panel_install.sh</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> panel_install.sh</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./panel_install.sh</span></span></code></pre></div><h2 id="agent-升级" tabindex="-1">agent 升级 <a class="header-anchor" href="#agent-升级" aria-label="Permalink to &quot;agent 升级&quot;">​</a></h2><p><strong>服务器</strong> 页选择服务器 → <strong>升级</strong>，留空版本即使用最新版；点 <strong>多选</strong> 可以批量升级。也可以在服务器上重新运行服务器安装脚本。</p><p>面板升级后建议把 agent 也升级到同一版本：新功能（例如回程检测、订阅流量统计）需要新 agent，旧 agent 能照常转发，只是用不了这些功能。内核（Xray / sing-box / Snell）的版本在 <strong>落地 → 内核</strong> 里单独更换，见 <a href="./kernels">内核与协议</a>。</p><h3 id="流量可靠上报" tabindex="-1">流量可靠上报 <a class="header-anchor" href="#流量可靠上报" aria-label="Permalink to &quot;流量可靠上报&quot;">​</a></h3><p>先升级面板，再升级 agent。新版 agent 将已采集、待确认的转发流量保存在工作目录的 <code>traffic-*.json</code> 中，网络失败或重启后继续重试；面板按批次去重，规则流量、共享用量和统计记录一起提交。请保留该目录及文件，容器部署需要保留 agent 数据卷。</p><p>旧 agent 仍可向新版面板上报，但不能获得跨重试去重和本地待发送缓冲的保障。新版 agent 连接不支持 <code>/flow/upload/v2</code> 的旧面板时会保留待上报数据，升级面板后继续发送。缓冲保护已落盘的采样；进程突然退出前尚未采集或落盘的字节无法补回。</p><p>面板游标因旧备份恢复或数据库重建而丢失时，节点会保留当前待确认批次，重新建立上报流并继续发送。完整流量数据备份现在同时保存去重游标；导入旧格式完整备份会清理所恢复节点的旧游标，让节点自动重新建立上报流。部分数据导入不替换游标。已被节点确认并删除、但不在备份中的历史用量不能凭空恢复。</p><p>明确被面板拒绝的批次会拆分重试，正常条目继续入账。仍无效的单条记录或批次身份冲突会保存在同目录的 <code>traffic-*.json.rejected-*.json</code>，并打印日志；这些记录不自动重新入账，需要检查配置和账目后人工处理。留档或队列保存失败时保留原批次。普通网络错误、代理返回的错误页和无法识别的响应不会触发丢弃。</p><h2 id="修复面板内升级" tabindex="-1">修复面板内升级 <a class="header-anchor" href="#修复面板内升级" aria-label="Permalink to &quot;修复面板内升级&quot;">​</a></h2><p>面板内升级提示“部署docker-compose.yml不可用”时：3.0.6 及更早版本的面板内升级会把后端容器的部署目录挂载弄丢，之后面板内升级会一直提示这个错误。数据不受影响，修复一次即可：</p><ol><li><p>在服务器上进入存放 <code>docker-compose.yml</code> 和 <code>.env</code> 的目录（常见为 <code>/root</code>，或当初运行安装脚本的目录），用 <code>ls</code> 确认这两个文件都在</p></li><li><p>执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force-recreate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frontend</span></span></code></pre></div></li></ol><p>也可以在该目录运行 3.0.7 及以后的安装脚本，选“更新面板”，会顺带修复。</p><h2 id="发布仓库是私有仓库" tabindex="-1">发布仓库是私有仓库 <a class="header-anchor" href="#发布仓库是私有仓库" aria-label="Permalink to &quot;发布仓库是私有仓库&quot;">​</a></h2><p>自己 fork 后把仓库设为私有时，GitHub 不再对外提供 Release 文件和镜像，面板内升级、服务器安装和 agent 升级都会失败。给面板配置一个令牌即可恢复（官方仓库 kure29/flyx 是公开的，不需要这一步）：</p><ol><li>在 GitHub <strong>Settings</strong> → <strong>Developer settings</strong> → <strong>Personal access tokens (classic)</strong> 新建令牌，勾选 <code>repo</code>；面板内升级还要拉取私有镜像，再勾选 <code>read:packages</code>。</li><li>在面板部署目录的 <code>.env</code> 里加一行 <code>GITHUB_TOKEN=令牌</code>，然后 <code>docker compose up -d</code> 重建后端（旧版 <code>docker-compose.yml</code> 需要在 <code>backend.environment</code> 里加上 <code>GITHUB_TOKEN: ${GITHUB_TOKEN:-}</code>，见 <a href="./faq">常见问题</a>）。令牌只在面板服务器上，不会显示在网页里，也不会进入备份。</li><li><strong>设置</strong> → <strong>服务器与监控</strong> 打开 <strong>GitHub 加速</strong>，加速地址选 <strong>面板中转</strong>。服务器从面板下载 agent 和安装脚本，令牌只留在面板上，不会下发到服务器。</li></ol><p>之后面板内升级、服务器 <strong>升级</strong> 按钮和面板生成的安装命令都和以前一样使用。用 Docker 方式部署的服务器拉取私有镜像前，需要在服务器上先 <code>docker login ghcr.io</code>（用户名是 GitHub 用户名，密码是带 <code>read:packages</code> 的令牌）。</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>面板经中转下载私有仓库的文件需要 3.5.7 或更新的版本。面板还是旧版本时，先在部署目录手动升级一次：<code>docker login ghcr.io</code> 后，把 <code>.env</code> 里的 <code>FLYX_VERSION</code> 改成新版本号，再运行 <code>docker compose pull &amp;&amp; docker compose up -d</code>。</p></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>面板中转对能访问面板地址的人开放，配置令牌后，私有仓库的 Release 文件（agent、安装脚本、compose 文件）也能经面板中转下载，源码不会。</p></div>',40)])])}const g=a(t,[["render",d]]);export{k as __pageData,g as default};
